using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using BurhanNexus.HMS.Core.Domain;
using BurhanNexus.HMS.Core.Licensing;

namespace BurhanNexus.HMS.Infrastructure.Licensing;

/// <summary>
/// Activation key format:  BNHMS1-{base64url(payload json)}.{base64url(ECDSA P-256 / SHA-256 signature)}
/// Only the vendor PUBLIC key is shipped with the software. Keys are generated by the separate
/// Burhan Nexus licence generator that holds the private key.
/// </summary>
public sealed class EcdsaLicenseKeyVerifier : ILicenseKeyVerifier
{
    public const string Prefix = "BNHMS1-";

    /// <summary>Burhan Nexus licence signing public key (not a secret).</summary>
    public const string VendorPublicKeyPem = """
        -----BEGIN PUBLIC KEY-----
        MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEAhTYgoFeY7+iHZoq/F5d5ESpczKN
        BOI3XoSkwzexEmneWuFEanxHx6YJRUep8mgxpI8RVhhVUEfhhDrnNIJFKQ==
        -----END PUBLIC KEY-----
        """;

    public static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        Converters = { new JsonStringEnumConverter() }
    };

    private readonly string _publicKeyPem;

    public EcdsaLicenseKeyVerifier(string? publicKeyPem = null) => _publicKeyPem = publicKeyPem ?? VendorPublicKeyPem;

    public bool TryVerify(string activationKey, out LicenseKeyPayload? payload, out string error)
    {
        payload = null;
        error = "The activation key is not valid.";
        var key = new string((activationKey ?? string.Empty).Where(c => !char.IsWhiteSpace(c)).ToArray());
        if (!key.StartsWith(Prefix, StringComparison.Ordinal)) return false;

        var body = key[Prefix.Length..];
        var dot = body.IndexOf('.');
        if (dot <= 0 || dot == body.Length - 1) return false;

        byte[] payloadBytes, signature;
        try
        {
            payloadBytes = Base64UrlDecode(body[..dot]);
            signature = Base64UrlDecode(body[(dot + 1)..]);
        }
        catch (FormatException)
        {
            return false;
        }

        using var ecdsa = ECDsa.Create();
        ecdsa.ImportFromPem(_publicKeyPem);
        if (!ecdsa.VerifyData(payloadBytes, signature, HashAlgorithmName.SHA256, DSASignatureFormat.IeeeP1363FixedFieldConcatenation))
        {
            error = "The activation key signature is not valid.";
            return false;
        }

        try
        {
            payload = JsonSerializer.Deserialize<LicenseKeyPayload>(payloadBytes, JsonOptions);
        }
        catch (JsonException)
        {
            payload = null;
        }

        if (payload is null || payload.Product != "BNHMS" || payload.V != 1)
        {
            error = "The activation key is not for this product.";
            payload = null;
            return false;
        }
        if (payload.Type is not (LicenseType.Annual or LicenseType.Lifetime))
        {
            error = "The activation key has an unsupported licence type.";
            payload = null;
            return false;
        }
        if (payload.Type == LicenseType.Annual && payload.ExpiresUtc is null)
        {
            error = "The annual activation key has no expiry date.";
            payload = null;
            return false;
        }

        error = string.Empty;
        return true;
    }

    /// <summary>Creates a key. Used by the vendor generator tool and by automated tests only.</summary>
    public static string CreateKey(LicenseKeyPayload payload, string privateKeyPem)
    {
        var json = JsonSerializer.SerializeToUtf8Bytes(payload, JsonOptions);
        using var ecdsa = ECDsa.Create();
        ecdsa.ImportFromPem(privateKeyPem);
        var sig = ecdsa.SignData(json, HashAlgorithmName.SHA256, DSASignatureFormat.IeeeP1363FixedFieldConcatenation);
        return Prefix + Base64UrlEncode(json) + "." + Base64UrlEncode(sig);
    }

    public static string Fingerprint(string activationKey)
    {
        var key = new string((activationKey ?? string.Empty).Where(c => !char.IsWhiteSpace(c)).ToArray());
        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(key)))[..16];
    }

    private static string Base64UrlEncode(byte[] data) =>
        Convert.ToBase64String(data).TrimEnd('=').Replace('+', '-').Replace('/', '_');

    private static byte[] Base64UrlDecode(string s)
    {
        var t = s.Replace('-', '+').Replace('_', '/');
        switch (t.Length % 4)
        {
            case 2: t += "=="; break;
            case 3: t += "="; break;
            case 1: throw new FormatException();
        }
        return Convert.FromBase64String(t);
    }
}
